section.code:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://faion.net/schemas/java-jpa-hibernate.json",
  "type": "object",
  "required": ["spring_boot_version", "ddl_auto", "open_in_view", "entities", "migrations_paired", "fetch_audit"],
  "properties": {
    "spring_boot_version": {"type": "string", "pattern": "^3\\."},
    "ddl_auto": {"const": "validate"},
    "open_in_view": {"const": false},
    "entities": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["class", "business_key", "associations_lazy", "uses_lombok_data"],
        "properties": {
          "class": {"type": "string"},
          "business_key": {"type": "string", "minLength": 1},
          "associations_lazy": {"type": "boolean", "const": true},
          "uses_lombok_data": {"type": "boolean", "const": false},
          "has_audit_timestamps": {"type": "boolean", "const": true},
          "version_column": {"type": "boolean"},
          "associations": {
            "type": "array",
            "items": {
              "type": "object",
              "required": ["kind", "justification"],
              "properties": {
                "kind": {"enum": ["OneToMany", "ManyToOne", "ManyToMany", "OneToOne"]},
                "cascade": {"type": "string"},
                "fetch": {"enum": ["LAZY", "EAGER"]},
                "justification": {"type": "string", "minLength": 10}
              }
            }
          }
        }
      }
    },
    "narrow_repository": {
      "type": "object",
      "required": ["interface_name", "extends_jparepository_directly"],
      "properties": {
        "interface_name": {"type": "string", "pattern": "^[A-Z][A-Za-z0-9]+Repository$"},
        "extends_jparepository_directly": {"type": "boolean", "const": false},
        "method_count": {"type": "integer", "minimum": 1, "maximum": 12}
      }
    },
    "service": {
      "type": "object",
      "required": ["class_name", "uses_dto_projection_on_reads"],
      "properties": {
        "class_name": {"type": "string", "pattern": "^[A-Z][A-Za-z0-9]+Service$"},
        "uses_dto_projection_on_reads": {"type": "boolean", "const": true},
        "uses_joinfetch_or_entitygraph": {"type": "boolean", "const": true},
        "readonly_tx_on_queries": {"type": "boolean", "const": true}
      }
    },
    "migrations_paired": {"type": "boolean", "const": true},
    "fetch_audit": {
      "type": "object",
      "required": ["eager_associations_found"],
      "properties": {
        "eager_associations_found": {"type": "array", "items": {"type": "string"}, "maxItems": 0}
      }
    },
    "forbidden_patterns_found": {"type": "array", "items": {"type": "string"}, "maxItems": 0}
  }
}

example.code:
{
  "spring_boot_version": "3.2.1",
  "ddl_auto": "validate",
  "open_in_view": false,
  "entities": [
    {
      "class": "com.acme.billing.Invoice",
      "business_key": "invoiceNumber",
      "associations_lazy": true,
      "uses_lombok_data": false,
      "has_audit_timestamps": true,
      "version_column": true,
      "associations": [
        {"kind": "OneToMany", "cascade": "PERSIST", "fetch": "LAZY", "justification": "Lines are owned by Invoice; persist with parent"}
      ]
    }
  ],
  "narrow_repository": {"interface_name": "InvoiceRepository", "extends_jparepository_directly": false, "method_count": 5},
  "service": {"class_name": "InvoiceService", "uses_dto_projection_on_reads": true, "uses_joinfetch_or_entitygraph": true, "readonly_tx_on_queries": true},
  "migrations_paired": true,
  "fetch_audit": {"eager_associations_found": []},
  "forbidden_patterns_found": []
}
